	@ParameterizedTest
	@EnumSource(Origin.class)
	void onePreparedStepRebindsTheActualGraphDomain(Origin origin, @TempDir File dataDir) throws Exception {
		try (Fixture fixture = new Fixture(dataDir)) {
			fixture.loadRepeatedNamedGraphs();
			for (IRI graph : List.of(G1, G2, G3)) {
				fixture.add(VF.createIRI("urn:selected:unique:s"), VF.createIRI(graph.stringValue() + ":unique-p"),
						VF.createLiteral("unique"), graph);
			}
			fixture.ready();
			try (SailDataset dataset = fixture.store.getBackingStore()
					.getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ)) {
				SailDatasetTripleTermSource source = new SailDatasetTripleTermSource(VF, dataset);
				EvaluationStatistics statistics = fixture.store.getBackingStore().getEvaluationStatistics();
				EvaluationStrategy strategy = fixture.store.getEvaluationStrategyFactory()
						.createEvaluationStrategy(null, source, statistics);
				TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, DISTINCT, null)
						.getTupleExpr();
				expression = strategy.optimize(expression, statistics, EmptyBindingSet.getInstance());
				QueryEvaluationStep prepared = strategy.precompile(expression);
				for (IRI selected : List.of(G1, G3, G2, VF.createIRI("urn:selected:missing"), G1)) {
					BindingSet input = new ListBindingSet(List.of("g"), selected);
					input = switch (origin) {
					case REQUEST -> BindingSetOrigin.requestInput(input);
					case LOCAL -> BindingSetOrigin.produced(input, Set.of("g"));
					case UNKNOWN -> BindingSetOrigin.with(input, BindingSetOrigin.of(input));
					};
					Map<BindingSet, Integer> bag = new HashMap<>();
					try (CloseableIteration<BindingSet> rows = prepared.evaluate(input)) {
						while (rows.hasNext()) {
							Fixture.addRow(bag, rows.next());
						}
					}
					assertEquals(fixture.directRows(fixture.memory, input), bag, origin + ", selector=" + selected);
				}
			}
		}
	}

