	@ParameterizedTest
	@EnumSource(Origin.class)
	void selectedGraphCloneRepreparesAndAlternatesBoundAndUnboundInputs(Origin origin, @TempDir File dataDir)
			throws Exception {
		try (Fixture fixture = new Fixture(dataDir)) {
			fixture.loadRepeatedNamedGraphs();
			try (PreparedGraph prepared = new PreparedGraph(fixture, DISTINCT, Function.identity())) {
				assertEquals(fixture.directRows(fixture.memory, EmptyBindingSet.getInstance()),
						prepared.rows(EmptyBindingSet.getInstance()));
				assertSelectedGraphAccess(prepared.pattern);
				TupleExpr cloned = prepared.expression.clone();
				StatementPattern clonedBody = firstStatementPattern(cloned);
				assertNotNull(clonedBody);
				assertEquals(StatementPattern.class, clonedBody.getClass(), "logical clone must contain no carrier");
				assertTrue(clonedBody.getParentNode() instanceof Graph, "logical GRAPH must survive selection/clone");
				assertEquals(prepared.pattern.isIndependentInputScope(), clonedBody.isIndependentInputScope());
				QueryEvaluationStep rebound = prepared.strategy.precompile(cloned);
				for (Value selector : new Value[] { G2, null, G1, VF.createIRI("urn:selected:missing"), null }) {
					BindingSet input = selector == null ? EmptyBindingSet.getInstance()
							: input(origin, "g", selector);
					Map<BindingSet, Integer> expected = fixture.directRows(fixture.memory, input);
					assertEquals(expected, prepared.rows(input), "original, " + origin + ", " + selector);
					assertEquals(expected, collect(rebound, input), "clone, " + origin + ", " + selector);
					if (selector == null) {
						assertSelectedGraphAccess(prepared.pattern);
						assertSelectedGraphAccess(clonedBody);
					} else {
						assertFalse("selected".equals(prepared.pattern.getStringMetricPlanned(GRAPH_SKIP_DECISION)),
								"bound selector uses ordinary membership; " + origin + ", " + selector);
						assertFalse("selected".equals(clonedBody.getStringMetricPlanned(GRAPH_SKIP_DECISION)),
								"cloned bound selector uses ordinary membership; " + origin + ", " + selector);
					}
				}
			}
		}
	}

