	@ParameterizedTest
	@EnumSource(IdFilterLocation.class)
	void selectedDomainPreservesLoweredBodyAndVariableIdFiltersBeforeSkipping(IdFilterLocation location,
			@TempDir File dataDir) throws Exception {
		try (Fixture fixture = new Fixture(dataDir)) {
			IRI rejectedPredicate = VF.createIRI("urn:selected:typed:iri-only");
			for (IRI graph : List.of(G1, G2, G3)) {
				fixture.add(VF.createIRI("urn:selected:typed:iri-only-subject"), rejectedPredicate,
						VF.createIRI("urn:selected:typed:iri-only-object"), graph);
				for (int predicate = 0; predicate < 4; predicate++) {
					for (int row = 0; row < 8; row++) {
						IRI name = VF.createIRI("urn:selected:typed:p:" + predicate);
						fixture.add(VF.createIRI("urn:selected:typed:reject:" + row), name,
								VF.createIRI("urn:selected:typed:iri:" + row), graph);
						fixture.add(VF.createIRI("urn:selected:typed:accept:" + row), name,
								VF.createLiteral("literal-" + row), graph);
					}
				}
			}
			fixture.ready();
			try (var first = fixture.nativeConnection.getStatements(null, rejectedPredicate,
					null, false, G1, G2, G3)) {
				assertTrue(first.hasNext());
				while (first.hasNext()) {
					assertTrue(first.next().getObject().isIRI(),
							"every possible raw representative of this prefix must fail the filter");
				}
			}
			String oracle = "SELECT DISTINCT ?p WHERE { GRAPH ?g { ?s ?p ?o FILTER(isLiteral(?o)) } }";
			try (PreparedGraph prepared = new PreparedGraph(fixture, DISTINCT, Function.identity())) {
				// This is the existing lowered native restriction contract: the eliminated scalar predicate is
				// represented on either the scan or its original object Var, both consumed by LmdbValueIdFilter.
				if (location == IdFilterLocation.BODY) {
					prepared.pattern.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:LITERAL");
				} else {
					prepared.pattern.getObjectVar()
							.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER,
									"object:LITERAL");
				}
				assertEquals(fixture.rows(fixture.memoryConnection, oracle, null, null),
						prepared.rows(EmptyBindingSet.getInstance()));
				assertSelectedGraphAccess(prepared.pattern);
				assertEquals(4, prepared.pattern.getSourceRowsMatchedActual(), "one accepted row per predicate");
				assertTrue(prepared.pattern.getSourceRowsFilteredActual() > 0, "rejected first representatives count");
			}
		}
	}

	@Test
	void unsupportedStatementOrderRetainsOrdinaryFailureAndOrder(@TempDir File dataDir) throws Exception {
		try (Fixture fixture = new Fixture(dataDir)) {
			fixture.loadRepeatedNamedGraphs();
			try (PreparedGraph prepared = new PreparedGraph(fixture, DISTINCT, Function.identity())) {
				prepared.pattern.setOrder(prepared.pattern.getPredicateVar());
				QueryEvaluationException failure = assertThrows(QueryEvaluationException.class,
						() -> prepared.rows(EmptyBindingSet.getInstance()));
				assertInstanceOf(UnsupportedOperationException.class, failure.getCause(),
						"native ordered retrieval is unsupported and must retain the ordinary failure");
				assertEquals(prepared.pattern.getStatementOrder(), firstStatementPattern(prepared.expression.clone())
						.getStatementOrder(), "ordinary lookup clone must preserve order");
				assertFalse(LmdbDistinctCursorSkipSupport.ACCESS_MODE.equals(prepared.pattern.getStringMetricPlanned(
						TelemetryMetricNames.PLANNED_INDEX_ACCESS_MODE)), "unsupported fused order must fall back");
				assertFalse("selected".equals(prepared.pattern.getStringMetricPlanned(GRAPH_SKIP_DECISION)));
			}
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void opaqueFallbackKeepsUnknownCountersAndClosesOnCompletionOrFailure(boolean fail,
			@TempDir File dataDir) throws Exception {
		try (Fixture fixture = new Fixture(dataDir)) {
			fixture.loadRepeatedNamedGraphs();
			List<OpaqueSource> sources = new ArrayList<>();
			try (PreparedGraph prepared = new PreparedGraph(fixture, DISTINCT, source -> {
				OpaqueSource opaque = new OpaqueSource(source, fail);
				sources.add(opaque);
				return opaque;
			})) {
				if (fail) {
					QueryEvaluationException failure = assertThrows(QueryEvaluationException.class,
							() -> prepared.rows(EmptyBindingSet.getInstance()));
					assertEquals("opaque source failure", failure.getMessage());
				} else {
					assertEquals(fixture.directRows(fixture.memory, EmptyBindingSet.getInstance()),
							prepared.rows(EmptyBindingSet.getInstance()));
					StatementPattern quad = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
							prepared.pattern.getSubjectVar().clone(), prepared.pattern.getPredicateVar().clone(),
							prepared.pattern.getObjectVar().clone(), Var.of("g", G1));
					QueryEvaluationStep boundary = new StatementPatternQueryEvaluationStep(quad,
							new QueryEvaluationContext.Minimal((Dataset) null), sources.getFirst());
					try (CloseableIteration<BindingSet> rows = boundary.evaluate(EmptyBindingSet.getInstance())) {
						IndexReportingIterator metrics = assertInstanceOf(IndexReportingIterator.class, rows);
						assertTrue(rows.hasNext());
						assertAll(
								() -> assertEquals(-1, metrics.getSourceRowsScannedActual()),
								() -> assertEquals(-1, metrics.getSourceRowsMatchedActual()),
								() -> assertEquals(-1, metrics.getSourceRowsFilteredActual()),
								() -> assertEquals(-1, metrics.getDistinctCursorSkipCountActual()),
								() -> assertEquals(-1, metrics.getDistinctCursorSkipSeekCountActual()));
					}
				}
				OpaqueSource source = sources.getFirst();
				assertTrue(source.statementOpens > 0);
				assertEquals(source.statementOpens, source.statementCloses);
				assertEquals(source.contextOpens, source.contextCloses);
				assertTrue(prepared.dataset.getSnapshotEpoch().isPresent());
			}
		}
	}

